+1|// Stock market bubble chart + linked data table.
+2|// - Bubble size: sqrt-scaled market cap (ETFs get a uniform size).
+3|// - Bubble color: sector.
+4|// - Layout: d3-force with per-sector forceX/forceY cluster centers + forceCollide.
+5|// - Selection: clicking a bubble or row highlights the matching entity in both views.
+6|
+7|const WIDTH = 720;
+8|const HEIGHT = 720;
+9|const MARGIN = { top: 20, right: 150, bottom: 20, left: 20 };
+10|const PLOT_W = WIDTH - MARGIN.left - MARGIN.right;
+11|const PLOT_H = HEIGHT - MARGIN.top - MARGIN.bottom;
+12|
+13|const SECTOR_ORDER = ["Information Technology", "Industry", "Energy", "Financial", "ETF"];
+14|
+15|const SECTOR_COLORS = {
+16|    "Information Technology": "#1f77b4",
+17|    "Industry":               "#ff7f0e",
+18|    "Energy":                 "#2ca02c",
+19|    "Financial":              "#9467bd",
+20|    "ETF":                    "#8c8c8c"
+21|};
+22|
+23|// Fixed cluster-center offsets (fraction of plot area) so the layout is deterministic.
+24|// Centers are kept near the middle of the plot so clusters don't fly to the edges.
+25|const CLUSTER_OFFSETS = {
+26|    "Information Technology": { x: 0.30, y: 0.32 },
+27|    "Industry":               { x: 0.70, y: 0.32 },
+28|    "Energy":                 { x: 0.30, y: 0.72 },
+29|    "Financial":              { x: 0.70, y: 0.72 },
+30|    "ETF":                    { x: 0.50, y: 0.52 }
+31|};
+32|
+33|const MIN_RADIUS = 14;
+34|const MAX_RADIUS = 56;
+35|const ETF_RADIUS = 22;      // uniform size for all ETFs
+36|const MIN_LABEL_RADIUS = 12;
+37|
+38|function formatMarketCap(value) {
+39|    if (value == null || !isFinite(value) || value <= 0) return "N/A";
+40|    const abs = Math.abs(value);
+41|    if (abs >= 1e12) return (value / 1e12).toFixed(2) + "T";
+42|    if (abs >= 1e9)  return (value / 1e9).toFixed(2)  + "B";
+43|    if (abs >= 1e6)  return (value / 1e6).toFixed(2)  + "M";
+44|    if (abs >= 1e3)  return (value / 1e3).toFixed(2)  + "K";
+45|    return value.toFixed(0);
+46|}
+47|
+48|function parseRow(d) {
+49|    const mc = d.marketCap ? parseFloat(d.marketCap) : NaN;
+50|    return {
+51|        ticker: d.ticker,
+52|        name: d["full name"],
+53|        sector: d.sector,
+54|        marketCap: isFinite(mc) ? mc : null,
+55|        country: d.country || "",
+56|        website: d.website || "",
+57|        isETF: d.sector === "ETF"
+58|    };
+59|}
+60|
+61|d3.csv("data/stock-descriptions.csv", parseRow).then(data => {
+62|    // Deterministic order: by sector (fixed order), then by descending market cap, then ticker.
+63|    data.sort((a, b) => {
+64|        const sa = SECTOR_ORDER.indexOf(a.sector);
+65|        const sb = SECTOR_ORDER.indexOf(b.sector);
+66|        if (sa !== sb) return sa - sb;
+67|        const ma = a.marketCap ?? -1;
+68|        const mb = b.marketCap ?? -1;
+69|        if (mb !== ma) return mb - ma;
+70|        return d3.ascending(a.ticker, b.ticker);
+71|    });
+72|
+73|    const nonEtfCaps = data.filter(d => !d.isETF && d.marketCap > 0).map(d => d.marketCap);
+74|    const capExtent = d3.extent(nonEtfCaps);
+75|    const radiusScale = d3.scaleSqrt().domain(capExtent).range([MIN_RADIUS, MAX_RADIUS]);
+76|
+77|    data.forEach(d => {
+78|        d.radius = d.isETF ? ETF_RADIUS : radiusScale(d.marketCap);
+79|        const c = CLUSTER_OFFSETS[d.sector];
+80|        d.cx = MARGIN.left + c.x * PLOT_W;
+81|        d.cy = MARGIN.top  + c.y * PLOT_H;
+82|        // Deterministic starting positions (no randomness).
+83|        d.x = d.cx;
+84|        d.y = d.cy;
+85|    });
+86|
+87|    renderBubbleChart(data);
+88|    renderTable(data);
+89|});
+90|
+91|function renderBubbleChart(data) {
+92|    const svg = d3.select("#bubble-chart")
+93|        .attr("width", WIDTH)
+94|        .attr("height", HEIGHT)
+95|        .attr("viewBox", `0 0 ${WIDTH} ${HEIGHT}`);
+96|
+97|    const g = svg.append("g").attr("class", "bubbles-layer");
+98|
+99|    const bubbles = g.selectAll("circle.bubble")
+100|        .data(data, d => d.ticker)
+101|        .join("circle")
+102|        .attr("class", "bubble")
+103|        .attr("r", d => d.radius)
+104|        .attr("fill", d => SECTOR_COLORS[d.sector])
+105|        .attr("cx", d => d.x)
+106|        .attr("cy", d => d.y)
+107|        .on("click", (event, d) => selectTicker(d.ticker))
+108|        .on("mouseover", function(event, d) {
+109|            // ETFs lack full metadata — skip tooltip per spec.
+110|            if (d.isETF) return;
+111|            const tt = d3.select("#tooltip");
+112|            tt.classed("visible", true)
+113|              .html(`
+114|                <div class="ttip-ticker">${d.ticker}</div>
+115|                <div><strong>Name:</strong> ${d.name}</div>
+116|                <div><strong>Sector:</strong> ${d.sector}</div>
+117|              `)
+118|              .style("left", (event.pageX + 12) + "px")
+119|              .style("top",  (event.pageY + 12) + "px");
+120|        })
+121|        .on("mousemove", function(event, d) {
+122|            if (d.isETF) return;
+123|            d3.select("#tooltip")
+124|              .style("left", (event.pageX + 12) + "px")
+125|              .style("top",  (event.pageY + 12) + "px");
+126|        })
+127|        .on("mouseout", function() {
+128|            d3.select("#tooltip").classed("visible", false);
+129|        });
+130|
+131|    const labels = g.selectAll("text.bubble-label")
+132|        .data(data, d => d.ticker)
+133|        .join("text")
+134|        .attr("class", "bubble-label")
+135|        .attr("text-anchor", "middle")
+136|        .attr("dominant-baseline", "central")
+137|        .attr("font-size", d => Math.max(9, Math.min(18, d.radius * 0.55)))
+138|        .text(d => d.radius >= MIN_LABEL_RADIUS ? d.ticker : "")
+139|        .attr("x", d => d.x)
+140|        .attr("y", d => d.y);
+141|
+142|    const sim = d3.forceSimulation(data)
+143|        .force("x", d3.forceX(d => d.cx).strength(0.18))
+144|        .force("y", d3.forceY(d => d.cy).strength(0.18))
+145|        .force("collide", d3.forceCollide(d => d.radius + 1.5).iterations(3))
+146|        .stop();
+147|
+148|    // Fixed tick count → deterministic final positions.
+149|    const TICKS = 300;
+150|    for (let i = 0; i < TICKS; i++) sim.tick();
+151|
+152|    bubbles.attr("cx", d => d.x).attr("cy", d => d.y);
+153|    labels.attr("x",  d => d.x).attr("y",  d => d.y);
+154|
+155|    renderLegend(svg);
+156|}
+157|
+158|function renderLegend(svg) {
+159|    const legend = svg.append("g")
+160|        .attr("class", "legend")
+161|        .attr("transform", `translate(${WIDTH - MARGIN.right + 20}, ${MARGIN.top + 10})`);
+162|
+163|    legend.append("text")
+164|        .attr("x", 0).attr("y", -6)
+165|        .attr("font-size", 13)
+166|        .attr("font-weight", 600)
+167|        .text("Sector");
+168|
+169|    const items = legend.selectAll("g.legend-item")
+170|        .data(SECTOR_ORDER)
+171|        .join("g")
+172|        .attr("class", "legend-item")
+173|        .attr("transform", (_, i) => `translate(0, ${i * 22 + 8})`);
+174|
+175|    items.append("circle")
+176|        .attr("cx", 8).attr("cy", 8).attr("r", 7)
+177|        .attr("fill", s => SECTOR_COLORS[s]);
+178|
+179|    items.append("text")
+180|        .attr("x", 22).attr("y", 12)
+181|        .text(s => s);
+182|}
+183|
+184|function renderTable(data) {
+185|    const tbody = d3.select("#stock-table tbody");
+186|
+187|    const rows = tbody.selectAll("tr")
+188|        .data(data, d => d.ticker)
+189|        .join("tr")
+190|        .attr("data-ticker", d => d.ticker)
+191|        .on("click", (event, d) => selectTicker(d.ticker));
+192|
+193|    rows.selectAll("td").remove();
+194|    rows.append("td").text(d => d.ticker);
+195|    rows.append("td").text(d => d.name || "");
+196|    rows.append("td").html(d =>
+197|        `<span class="sector-swatch" style="background:${SECTOR_COLORS[d.sector]}"></span>${d.sector}`
+198|    );
+199|    rows.append("td").text(d => d.isETF ? "—" : formatMarketCap(d.marketCap));
+200|}
+201|
+202|function selectTicker(ticker) {
+203|    d3.selectAll("circle.bubble").classed("selected", false);
+204|    d3.selectAll("#stock-table tbody tr").classed("selected", false);
+205|
+206|    d3.selectAll("circle.bubble")
+207|        .filter(d => d.ticker === ticker)
+208|        .classed("selected", true);
+209|
+210|    const selectedRow = d3.selectAll("#stock-table tbody tr")
+211|        .filter(d => d.ticker === ticker)
+212|        .classed("selected", true);
+213|
+214|    const node = selectedRow.node();
+215|    if (node && node.scrollIntoView) {
+216|        node.scrollIntoView({ block: "nearest", behavior: "auto" });
+217|    }
+218|}
+219|
[end of edit 1 / 1]

